/// rand draws 11 bits per float16 and 8 per bfloat16 element from PyTorch's MT19937 stream; random_() spans [0, 2**11] / [0, 2**8] for the floats and [0, max] for int8/int16; randint casts.
#[test]
fn reduced_precision_random_numbers_follow_the_cpu_stream() {
    let out = run(r#"
def draws(fn):
    torch.manual_seed(0)
    return fn()
check('rand_half', lambda: draws(lambda: torch.rand(8, dtype=torch.half)), ['T', [8], 'torch.float16', [0.333984375, 0.27294921875, 0.80712890625, 0.59375, 0.40771484375, 0.37255859375, 0.84521484375, 0.67529296875]], 0)
check('rand_bf16', lambda: draws(lambda: torch.rand(8, dtype=torch.bfloat16)), ['T', [8], 'torch.bfloat16', [0.671875, 0.18359375, 0.45703125, 0.75, 0.26171875, 0.98046875, 0.76171875, 0.40234375]], 0)
check('random_', lambda: [draws(lambda: torch.empty(6, dtype=d).random_()) for d in (torch.half, torch.bfloat16, torch.int8, torch.int16)], [['T', [6], 'torch.float16', [1277.0, 1017.0, 1661.0, 999.0, 982.0, 543.0]], ['T', [6], 'torch.bfloat16', [149.0, 179.0, 47.0, 62.0, 69.0, 112.0]], ['T', [6], 'torch.int8', [44, 47, 117, 64, 67, 123]], ['T', [6], 'torch.int16', [2732, 10799, 9845, 19648, 13123, 21243]]], 0)
check('randint', lambda: draws(lambda: torch.randint(-5, 5, (6,), dtype=torch.int8)), ['T', [6], 'torch.int8', [-1, 4, -2, -5, -2, 4]], 0)
check('uniform_', lambda: draws(lambda: torch.empty(5, dtype=torch.half).uniform_(-1, 1)).dtype, 'torch.float16', 0)
check('randn_dtype', lambda: draws(lambda: [torch.randn(3, dtype=torch.half).dtype, torch.randn(3, dtype=torch.bfloat16).dtype]), ['torch.float16', 'torch.bfloat16'], 0)
"#);
    assert_all_true(&out, 6);
}

/// repr of float16/bfloat16/int8/int16 tensors: PyTorch's formatter, with the dtype suffix.
#[test]
fn reduced_precision_tensors_print_as_pytorch() {
    let out = run(r#"
check('repr', lambda: [repr(torch.tensor([1.5, 2.25], dtype=torch.half)), repr(torch.tensor([0.1], dtype=torch.half)), repr(torch.tensor([[1e-5, 1000.]], dtype=torch.half)), repr(torch.tensor(3.25, dtype=torch.bfloat16)), repr(torch.tensor([1, -2], dtype=torch.int8)), repr(torch.tensor([300], dtype=torch.int16)), repr(torch.ones(2, dtype=torch.half, requires_grad=True)), repr(torch.zeros(0, dtype=torch.bfloat16))], ['tensor([1.5000, 2.2500], dtype=torch.float16)', 'tensor([0.1000], dtype=torch.float16)', 'tensor([[1.0014e-05, 1.0000e+03]], dtype=torch.float16)', 'tensor(3.2500, dtype=torch.bfloat16)', 'tensor([ 1, -2], dtype=torch.int8)', 'tensor([300], dtype=torch.int16)', 'tensor([1., 1.], dtype=torch.float16, requires_grad=True)', 'tensor([], dtype=torch.bfloat16)'], 0)
"#);
    assert_all_true(&out, 1);
}

/// torch.load reads PyTorch's HalfStorage/BFloat16Storage/CharStorage/ShortStorage records (2 or 1 bytes per element, bf16 as the upper float32 half); torch.save writes the same bytes and class names, and a Zipp checkpoint loads back.
#[test]
fn checkpoints_carry_half_bfloat16_char_and_short_storages() {
    let out = run(r#"
def loaded():
    d = torch.load("dtypes.pt")
    return [[k, d[k]] for k in sorted(d)]
def raw(t):
    # The storage record's bytes torch.save writes for `t`.
    import zipfile
    torch.save(t, "one.pt")
    with zipfile.ZipFile("one.pt") as z:
        return list(z.read([n for n in z.namelist() if n.endswith("/data/0")][0]))
def roundtrip():
    d = {"h": torch.tensor([1.5, -2.0, 65504.0, 6e-8, float("inf")], dtype=torch.half), "b": torch.tensor([1.5, -3.4e38], dtype=torch.bfloat16),
         "c": torch.tensor([-3, 4, 127], dtype=torch.int8), "s": torch.tensor([-300, 32767], dtype=torch.int16), "dt": [torch.half, torch.bfloat16, torch.int8, torch.int16],
         "p": torch.nn.Parameter(torch.ones(2, dtype=torch.half))}
    torch.save(d, "roundtrip.pt")
    back = torch.load("roundtrip.pt")
    return [[k, back[k]] for k in sorted(back)] + [type(back["p"]).__name__]
def names():
    import zipfile
    torch.save({"h": torch.ones(1, dtype=torch.half), "b": torch.ones(1, dtype=torch.bfloat16), "c": torch.ones(1, dtype=torch.int8), "s": torch.ones(1, dtype=torch.int16)}, "names.pt")
    with zipfile.ZipFile("names.pt") as z:
        pkl = [z.read(n) for n in z.namelist() if n.endswith("data.pkl")][0]
    return [w in pkl for w in (b"HalfStorage", b"BFloat16Storage", b"CharStorage", b"ShortStorage")]
check('load_pytorch', lambda: loaded(), [['b', ['T', [2, 2], 'torch.bfloat16', [1.5, -float("inf"), 0.10009765625, 9.183549615799121e-41]]], ['c', ['T', [4], 'torch.int8', [-3, 4, 127, -128]]], ['dtypes', ['torch.float16', 'torch.bfloat16', 'torch.int8', 'torch.int16']], ['h', ['T', [6], 'torch.float16', [1.5, -2.0, 65504.0, 5.960464477539063e-08, float("inf"), 0.0999755859375]]], ['p', ['T', [2], 'torch.bfloat16', [0.5, 0.25]]], ['s', ['T', [2], 'torch.int16', [-300, 32767]]], ['t', ['T', [4, 3], 'torch.float16', [0.0, 4.0, 8.0, 1.0, 5.0, 9.0, 2.0, 6.0, 10.0, 3.0, 7.0, 11.0]]]], 0)
check('bytes', lambda: [raw(torch.tensor([1.5, -2.0, 65504.0, 6e-8, float('nan')], dtype=torch.half)), raw(torch.tensor([1.5, -3.4e38, float('nan')], dtype=torch.bfloat16)), raw(torch.tensor([-3, 4], dtype=torch.int8)), raw(torch.tensor([-300, 32767], dtype=torch.int16))], [[0, 62, 0, 192, 255, 123, 1, 0, 0, 126], [192, 63, 128, 255, 192, 127], [253, 4], [212, 254, 255, 127]], 0)
check('roundtrip', lambda: roundtrip(), [['b', ['T', [2], 'torch.bfloat16', [1.5, -float("inf")]]], ['c', ['T', [3], 'torch.int8', [-3, 4, 127]]], ['dt', ['torch.float16', 'torch.bfloat16', 'torch.int8', 'torch.int16']], ['h', ['T', [5], 'torch.float16', [1.5, -2.0, 65504.0, 5.960464477539063e-08, float("inf")]]], ['p', ['T', [2], 'torch.float16', [1.0, 1.0]]], ['s', ['T', [2], 'torch.int16', [-300, 32767]]], 'Parameter'], 0)
check('names', lambda: names(), [True, True, True, True], 0)
"#);
    assert_all_true(&out, 4);
}

